import { cookies } from 'next/headers';

// ❌ OLD: Opting the whole page into dynamic rendering
// delays TTFB for the header, layout, and static marketing copy.
export const dynamic = 'force-dynamic';

export default async function Page() {
  const session = (await cookies()).get('session');
  const user = await fetchUser(session?.value);

  return (
    <main>
      <header className="hero">Static Brand Banner</header>
      <section className="user-info">Welcome {user.name}</section>
    </main>
  );
}

import { Suspense } from 'react';
import { cookies } from 'next/headers';

export const experimental_ppr = true;

async function UserProfile() {
  const session = (await cookies()).get('session');
  const user = await fetchUser(session?.value);
  return <span>Welcome {user.name}</span>;
}

export default function Page() {
  return (
    <main>
      {/* ✅ NEW: Pre-rendered statically at build time */}
      <header className="hero">Static Brand Banner</header>
      {/* ✅ NEW: Streams dynamically on request */}
      <Suspense fallback={<div className="skeleton">Loading user...</div>}>
        <UserProfile />
      </Suspense>
    </main>
  );
}
